d3 = import("https://cdn.jsdelivr.net/npm/d3@7.9.0/+esm")
Plot = import("https://cdn.jsdelivr.net/npm/@observablehq/plot@0.6.16/+esm")
mapaLib = import(new URL("assets/mapa.js", document.baseURI).href)
setoresGeo = FileAttachment("data/sectors.geojson").json()
parquesGeo = FileAttachment("data/parks.geojson").json()
setores = setoresGeo.features.map((f) =&gt; f.properties)

// ---------- formatação em pt-BR ----------
// sinal de menos tipográfico (−) no lugar do hífen
fmt = (x, c = 2) =&gt; x.toLocaleString("pt-BR", { minimumFractionDigits: c, maximumFractionDigits: c }).replace("-", "−")
fmtInt = (x) =&gt; x.toLocaleString("pt-BR")
fmtRenda = (x) =&gt; "R$ " + x.toLocaleString("pt-BR", { maximumFractionDigits: 1 })
DESTAQUE = "#fdae61"
TINTA = "#d9d4ca"
APAGADO = "#8d8a84"

// ---------- estatísticas por quintil (d3.quantile = mesmo método do pandas) ----------
estatQuintis = d3.range(1, 6).map((q) =&gt; {
  const g = setores.filter((d) =&gt; d.quintil === q);
  const t = g.map((d) =&gt; d.temperatura);
  return {
    quintil: q, rotulo: `Q${q}`, n: g.length,
    media: d3.mean(t), mediana: d3.median(t),
    q1: d3.quantile(t, 0.25), q3: d3.quantile(t, 0.75),
    distMedia: d3.mean(g, (d) =&gt; d.dist_park_m) / 1000,
    distMediana: d3.median(g, (d) =&gt; d.dist_park_m) / 1000,
    rendaMin: d3.min(g, (d) =&gt; d.income_median), rendaMax: d3.max(g, (d) =&gt; d.income_median),
    arvore: d3.mean(g, (d) =&gt; d.pct_tree), construido: d3.mean(g, (d) =&gt; d.pct_built), ndvi: d3.mean(g, (d) =&gt; d.ndvi_mean)
  };
})
Q1 = estatQuintis[0]
Q5 = estatQuintis[4]
mediaQ1aQ4 = d3.mean(estatQuintis.slice(0, 4), (d) =&gt; d.media)          // média das 4 médias de grupo
mediaQ1aQ4Setores = d3.mean(setores.filter((d) =&gt; d.quintil &lt; 5), (d) =&gt; d.temperatura)
difQ5 = Q5.media - mediaQ1aQ4
faixasRenda = estatQuintis.map((d) =&gt; ({ quintil: d.quintil, min: d.rendaMin, max: d.rendaMax }))
paradasTemp = [0.05, 0.25, 0.5, 0.75, 0.95].map((p) =&gt; d3.quantile(setores, p, (d) =&gt; d.temperatura))

// ---------- correlação de Spearman (renda × temperatura), com postos médios nos empates ----------
postos = (v) =&gt; {
  const ordem = d3.range(v.length).sort((a, b) =&gt; v[a] - v[b]);
  const r = new Array(v.length);
  for (let i = 0; i &lt; ordem.length; ) {
    let j = i;
    while (j + 1 &lt; ordem.length && v[ordem[j + 1]] === v[ordem[i]]) j++;
    for (let k = i; k &lt;= j; k++) r[ordem[k]] = (i + j) / 2 + 1;
    i = j + 1;
  }
  return r;
}
spearman = {
  const a = postos(setores.map((d) =&gt; d.income_median));
  const b = postos(setores.map((d) =&gt; d.temperatura));
  const ma = d3.mean(a), mb = d3.mean(b);
  return d3.sum(a, (x, i) =&gt; (x - ma) * (b[i] - mb)) /
    Math.sqrt(d3.sum(a, (x) =&gt; (x - ma) ** 2) * d3.sum(b, (x) =&gt; (x - mb) ** 2));
}

// ---------- critério de prioridade do estudo ----------
limiarP75 = d3.quantile(setores, 0.75, (d) =&gt; d.temperatura)
ehPrioritario = (d, quintis, limiar, distancia) =&gt;
  quintis.includes(d.quintil) && d.temperatura &gt; limiar && d.dist_park_m &gt; distancia
idsPrioritarios = new Set(setores.filter((d) =&gt; ehPrioritario(d, [1, 2], limiarP75, 2000)).map((d) =&gt; d.sector_id))
nPrio = idsPrioritarios.size
pctPrio = (100 * nPrio) / setores.length
ESPERADO_PRIO = 225   // contagem do notebook 06 (tabela de sensibilidade), usada só para conferência

// ---------- faixas de distância ao parque ----------
faixas = [
  { rotulo: "&lt; 0,5 km", min: 0, max: 500 },
  { rotulo: "0,5–1 km", min: 500, max: 1000 },
  { rotulo: "1–2 km", min: 1000, max: 2000 },
  { rotulo: "2–4 km", min: 2000, max: 4000 },
  { rotulo: "&gt; 4 km", min: 4000, max: Infinity }
]
estatFaixas = faixas.map((f) =&gt; {
  const g = setores.filter((d) =&gt; d.dist_park_m &gt;= f.min && d.dist_park_m &lt; f.max);
  return { ...f, n: g.length, media: d3.mean(g, (d) =&gt; d.temperatura), mediana: d3.median(g, (d) =&gt; d.temperatura) };
})
difPerto2a4 = estatFaixas[3].media - estatFaixas[0].media

// ---------- largura das áreas largas (.column-page), reativa ao redimensionar ----------
larguraLarga = Generators.observe((notificar) =&gt; {
  const alvo = document.getElementById("medida-pagina");
  const obs = new ResizeObserver(() =&gt; notificar(Math.max(320, alvo.clientWidth)));
  obs.observe(alvo);
  notificar(Math.max(320, alvo.clientWidth));
  return () =&gt; obs.disconnect();
})

2 Só os setores de maior renda são mais frescos

Entre cinco grupos de renda, só o de renda mais alta vive em setores mais frescos.

Os grupos Q1 a Q4 têm temperatura muito parecida: as medianas ficam entre  e  °C. Só o Q5 se separa,  °C abaixo da média dos outros quatro.

viewof quintilClicado = {
  // dispersão vertical fixa (semente) para os pontos não se sobreporem
  const aleatorio = d3.randomLcg(7);
  const desvio = new Map(setores.map((d) =&gt; [d.sector_id, (aleatorio() - 0.5) * 0.56]));
  const cor = (q) =&gt; (q === 5 ? DESTAQUE : APAGADO);
  const grafico = Plot.plot({
    width: larguraLarga,
    height: 380,
    marginLeft: 48,
    marginBottom: 44,
    style: { background: "transparent", color: TINTA, fontFamily: "'Source Sans 3', system-ui, sans-serif", fontSize: "12.5px" },
    // só graus inteiros no eixo (antes, ticks de meio grau arredondados apareciam repetidos: 27, 27, 28…)
    x: { label: "Temperatura de brilho da superfície (°C) →", grid: true,
         ticks: d3.range(Math.ceil(d3.min(setores, (d) =&gt; d.temperatura)), Math.floor(d3.max(setores, (d) =&gt; d.temperatura)) + 1),
         tickFormat: (d) =&gt; fmt(d, 0) },
    y: { domain: [5.6, 0.4], ticks: [1, 2, 3, 4, 5], tickFormat: (d) =&gt; `Q${d}`, label: null, tickSize: 0 },
    marks: [
      Plot.dot(setores, { x: "temperatura", y: (d) =&gt; d.quintil + desvio.get(d.sector_id), r: 1.6,
        fill: (d) =&gt; cor(d.quintil), fillOpacity: 0.32 }),
      Plot.ruleX([mediaQ1aQ4], { y1: 0.5, y2: 4.5, stroke: APAGADO, strokeDasharray: "3,3" }),
      Plot.text([mediaQ1aQ4], { x: (d) =&gt; d, y: 0.45, text: () =&gt; "média Q1–Q4", fill: APAGADO, dy: 0, textAnchor: "start", dx: 4 }),
      Plot.rect(estatQuintis, { x1: "q1", x2: "q3", y1: (d) =&gt; d.quintil - 0.32, y2: (d) =&gt; d.quintil + 0.32,
        fill: "none", stroke: (d) =&gt; (d.quintil === 5 ? DESTAQUE : TINTA), strokeWidth: 1.3 }),
      Plot.ruleX(estatQuintis, { x: "mediana", y1: (d) =&gt; d.quintil - 0.32, y2: (d) =&gt; d.quintil + 0.32,
        stroke: (d) =&gt; (d.quintil === 5 ? DESTAQUE : TINTA), strokeWidth: 2.5 }),
      Plot.dot(estatQuintis, { x: "media", y: "quintil", r: 4, fill: "#0e0e0e",
        stroke: (d) =&gt; (d.quintil === 5 ? DESTAQUE : TINTA), strokeWidth: 1.5 }),
      Plot.tip(estatQuintis, Plot.pointerY({
        x: "q3", y: "quintil", anchor: "left", fill: "#151515", stroke: "#444",
        title: (d) =&gt; [
          `Q${d.quintil} · ${fmtInt(d.n)} setores`,
          `renda mediana ${fmtRenda(d.rendaMin)} a ${fmtRenda(d.rendaMax)}`,
          `média ${fmt(d.media)} °C · mediana ${fmt(d.mediana)} °C`,
          `quartis ${fmt(d.q1)} a ${fmt(d.q3)} °C`,
          "clique para destacar no mapa"
        ].join("\n")
      }))
    ]
  });
  // clique: escolhe (ou desfaz) o quintil sob o ponteiro e avisa o mapa
  const caixa = html`&lt;div class="grafico-quintis"&gt;${grafico}&lt;/div&gt;`;
  caixa.value = null;
  grafico.addEventListener("input", (e) =&gt; e.stopPropagation());
  grafico.addEventListener("click", () =&gt; {
    const d = grafico.value;
    caixa.value = d && caixa.value !== d.quintil ? d.quintil : null;
    caixa.dispatchEvent(new Event("input", { bubbles: true }));
  });
  return caixa;
}







html`&lt;p class="legenda-grafico"&gt;Cada ponto é um setor. A caixa cobre os 50% do meio, o traço grosso é a mediana e o círculo é a média; a linha tracejada é a média dos grupos Q1 a Q4. Passe o mouse sobre um grupo para ver os números; clique para marcar os setores dele no &lt;a href="#explore-o-mapa"&gt;mapa&lt;/a&gt;${quintilClicado ? html` (agora: &lt;strong&gt;Q${quintilClicado}&lt;/strong&gt; destacado)` : ""}.&lt;/p&gt;`








Como ler o gráfico: cada faixa horizontal é um grupo de renda. Q1 reúne os setores de renda mais baixa e Q5 os de renda mais alta. Os grupos são posições relativas (cerca de um quinto dos setores cada), não linhas de pobreza.
Correlação de Spearman entre renda e temperatura: , uma associação moderada.
Isso quer dizer que não existe uma escada em que cada aumento de renda traz um pouco de frescor. A vantagem está concentrada no topo.

3 Não é só falta de árvore

A explicação mais óbvia, “onde a renda é menor, há menos árvores”, não se sustenta na média.

A hipótese inicial era que os setores de renda baixa teriam menos vegetação e mais área construída, e por isso seriam mais quentes. Os dados não confirmaram isso na média: o grupo de renda mais baixa tem até mais árvores e menos área construída do que os grupos intermediários.

html`&lt;table class="tabela-numeros"&gt;
  &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Grupo&lt;/th&gt;&lt;th&gt;Árvores (%)&lt;/th&gt;&lt;th&gt;Construído (%)&lt;/th&gt;&lt;th&gt;NDVI médio&lt;/th&gt;&lt;th&gt;Temperatura média&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
  &lt;tbody&gt;${estatQuintis.map((d) =&gt; html`&lt;tr class=${d.quintil === 5 ? "linha-destaque" : ""}&gt;
    &lt;td&gt;Q${d.quintil}&lt;/td&gt;&lt;td&gt;${fmt(d.arvore, 1)}&lt;/td&gt;&lt;td&gt;${fmt(d.construido, 1)}&lt;/td&gt;&lt;td&gt;${fmt(d.ndvi)}&lt;/td&gt;&lt;td&gt;${fmt(d.media)} °C&lt;/td&gt;&lt;/tr&gt;`)}
  &lt;/tbody&gt;&lt;/table&gt;
  &lt;p class="legenda-grafico"&gt;Médias por grupo de renda, calculadas a partir da tabela de setores.&lt;/p&gt;`






O contraste mais curioso está no topo: o Q5 tem a menor cobertura de árvores (%) e a maior área construída (%) entre os cinco grupos, e mesmo assim é o grupo mais fresco.
Também foi testado se o solo exposto e a grama seca explicariam a diferença, e essa explicação também não se sustentou. A vantagem do grupo de renda mais alta continua depois de levar em conta vegetação, área construída, solo, altitude e distância a parques.
O que isso sugere, sem provar: olhar a cobertura do solo a cada 10 metros não conta a história toda. O tipo de telhado, os materiais das construções, a altura dos prédios e o desenho das ruas também podem pesar na temperatura, e nada disso foi medido aqui.





  Distância de cada setor ao parque grande mais próximo: do roxo (até 500 m) ao amarelo (mais de 4 km). Contorno branco: parques.

4 Parques: perto é mais fresco, mas nem todos estão perto

 km de um parque para quem mora nos setores de maior renda.  km para quem mora nos de menor renda.

A análise considera os  parques acima de 10 hectares. Os setores mais próximos tendem a ser mais frescos, com uma diferença de cerca de  °C entre os setores a menos de 500 m e os que ficam entre 2 e 4 km. Essa relação não continua além de cerca de 4 km.

viewof faixasSel = Inputs.checkbox(faixas.map((f) =&gt; f.rotulo), {
  label: "Faixas de distância",
  value: faixas.map((f) =&gt; f.rotulo)
})







{
  const ativa = new Set(faixasSel);
  const faixaDe = (m) =&gt; faixas.find((f) =&gt; m &gt;= f.min && m &lt; f.max).rotulo;
  const maxKm = d3.max(setores, (d) =&gt; d.dist_park_m) / 1000;
  const selecionados = estatFaixas.filter((f) =&gt; ativa.has(f.rotulo));
  const grafico = Plot.plot({
    width: larguraLarga,
    height: 420,
    marginLeft: 48,
    marginBottom: 44,
    style: { background: "transparent", color: TINTA, fontFamily: "'Source Sans 3', system-ui, sans-serif", fontSize: "12.5px" },
    x: { label: "Distância ao parque grande mais próximo (km) →", domain: [0, Math.ceil(maxKm)], grid: true },
    y: { label: "↑ Temperatura (°C)", grid: true, tickFormat: (d) =&gt; fmt(d, 0) },
    marks: [
      Plot.dot(setores, { x: (d) =&gt; d.dist_park_m / 1000, y: "temperatura", r: 1.8,
        fill: (d) =&gt; (ativa.has(faixaDe(d.dist_park_m)) ? TINTA : "#3a3a3a"),
        fillOpacity: (d) =&gt; (ativa.has(faixaDe(d.dist_park_m)) ? 0.45 : 0.25) }),
      Plot.ruleX([0.5, 1, 2, 4], { stroke: "#555", strokeDasharray: "2,3" }),
      Plot.ruleY(selecionados, { y: "media", x1: (d) =&gt; d.min / 1000, x2: (d) =&gt; Math.min(d.max / 1000, maxKm),
        stroke: DESTAQUE, strokeWidth: 3 }),
      Plot.tip(setores, Plot.pointer({
        x: (d) =&gt; d.dist_park_m / 1000, y: "temperatura", fill: "#151515", stroke: "#444",
        filter: (d) =&gt; ativa.has(faixaDe(d.dist_park_m)),
        title: (d) =&gt; [
          `setor ${d.sector_id}`,
          `${fmt(d.dist_park_m / 1000)} km do parque · ${fmt(d.temperatura)} °C`,
          `Q${d.quintil} · renda mediana ${fmtRenda(d.income_median)}`
        ].join("\n")
      }))
    ]
  });
  const tabela = html`&lt;table class="tabela-numeros"&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Faixa&lt;/th&gt;&lt;th&gt;Setores&lt;/th&gt;&lt;th&gt;Temperatura média&lt;/th&gt;&lt;th&gt;Mediana&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;${selecionados.map((f) =&gt; html`&lt;tr&gt;&lt;td&gt;${f.rotulo}&lt;/td&gt;&lt;td&gt;${fmtInt(f.n)}&lt;/td&gt;&lt;td&gt;${fmt(f.media)} °C&lt;/td&gt;&lt;td&gt;${fmt(f.mediana)} °C&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;
  &lt;/table&gt;`;
  return html`&lt;div&gt;${grafico}
    &lt;p class="legenda-grafico"&gt;Cada ponto é um setor. Os traços na cor de destaque são a temperatura média de cada faixa selecionada. Desmarque faixas para compará-las; passe o mouse sobre um ponto para ver o setor.&lt;/p&gt;
    ${tabela}&lt;/div&gt;`;
}






Como os parques estão mais perto dos setores de maior renda, o benefício de frescor também se distribui de forma desigual.



Distância ao parque grande por faixa de renda.


Estar perto não quer dizer por causa. Setores vizinhos de parques podem ter outras características em comum, como o padrão de ocupação, que também pesam na temperatura. Mesmo assim, o padrão é firme: ele continua praticamente igual quando saem da conta os setores que têm um parque dentro dos seus limites.





  Em vermelho, os setores prioritários; em contorno claro, os parques grandes.
